//! The real host: every call goes through the `nugget:plugin` imports generated by wit-bindgen.

use crate::bindings::nugget::plugin as wit;
use crate::{Content, Document, Error, Result, fs, http, log::Level};

pub use wit::types::PluginError as WitError;

impl From<WitError> for Error {
    fn from(e: WitError) -> Self {
        match e {
            WitError::Invalid(m) => Error::Invalid(m),
            WitError::Unauthorized(m) => Error::Unauthorized(m),
            WitError::Network(m) => Error::Network(m),
            WitError::RateLimited(ms) => Error::RateLimited(ms),
            WitError::NotFound(m) => Error::NotFound(m),
            WitError::Denied(m) => Error::Denied(m),
            WitError::Cancelled => Error::Cancelled,
            WitError::Other(m) => Error::Other(m),
        }
    }
}

impl From<Error> for WitError {
    fn from(e: Error) -> Self {
        match e {
            Error::Invalid(m) => WitError::Invalid(m),
            Error::Unauthorized(m) => WitError::Unauthorized(m),
            Error::Network(m) => WitError::Network(m),
            Error::RateLimited(ms) => WitError::RateLimited(ms),
            Error::NotFound(m) => WitError::NotFound(m),
            Error::Denied(m) => WitError::Denied(m),
            Error::Cancelled => WitError::Cancelled,
            Error::Other(m) => WitError::Other(m),
        }
    }
}

pub(crate) fn http_send(req: http::Request) -> Result<http::Response> {
    let resp = wit::http::send(&wit::http::Request {
        method: req.method,
        url: req.url,
        headers: req.headers,
        body: req.body,
    })?;
    Ok(http::Response {
        status: resp.status,
        headers: resp.headers,
        body: resp.body,
    })
}

pub(crate) fn kv_get(key: &str) -> Result<Option<Vec<u8>>> {
    Ok(wit::kv::get(key)?)
}

pub(crate) fn kv_set(key: &str, value: &[u8]) -> Result<()> {
    Ok(wit::kv::set(key, value)?)
}

pub(crate) fn kv_delete(key: &str) -> Result<()> {
    Ok(wit::kv::delete(key)?)
}

pub(crate) fn kv_keys(prefix: &str) -> Result<Vec<String>> {
    Ok(wit::kv::keys(prefix)?)
}

pub(crate) fn secret_get(name: &str) -> Result<Option<String>> {
    Ok(wit::secrets::get(name)?)
}

pub(crate) fn secret_set(name: &str, value: &str) -> Result<()> {
    Ok(wit::secrets::set(name, value)?)
}

pub(crate) fn log(level: Level, msg: &str) {
    let level = match level {
        Level::Trace => wit::log::Level::Trace,
        Level::Debug => wit::log::Level::Debug,
        Level::Info => wit::log::Level::Info,
        Level::Warn => wit::log::Level::Warn,
        Level::Error => wit::log::Level::Error,
    };
    wit::log::log(level, msg)
}

pub(crate) fn now() -> i64 {
    wit::clock::now()
}

fn entry(e: wit::fs::DirEntry) -> fs::DirEntry {
    fs::DirEntry {
        name: e.name,
        is_dir: e.is_dir,
        size: e.size,
        modified_at: e.modified_at,
    }
}

pub(crate) fn fs_read_dir(root: &str, path: &str) -> Result<Vec<fs::DirEntry>> {
    Ok(wit::fs::read_dir(root, path)?
        .into_iter()
        .map(entry)
        .collect())
}

pub(crate) fn fs_read_file(root: &str, path: &str) -> Result<Vec<u8>> {
    Ok(wit::fs::read_file(root, path)?)
}

pub(crate) fn fs_stat(root: &str, path: &str) -> Result<fs::DirEntry> {
    Ok(entry(wit::fs::stat(root, path)?))
}

pub(crate) fn sink_upsert(doc: Document) -> Result<()> {
    Ok(wit::sink::upsert(&wit::types::Document {
        key: doc.key,
        title: doc.title,
        mime: doc.mime,
        content: match doc.content {
            Content::Text(t) => wit::types::Content::Text(t),
            Content::Bytes(b) => wit::types::Content::Bytes(b),
        },
        version: doc.version,
        modified_at: doc.modified_at,
        url: doc.url,
        metadata: doc.metadata.to_string(),
    })?)
}

pub(crate) fn sink_delete(key: &str) -> Result<()> {
    Ok(wit::sink::delete(key)?)
}

pub(crate) fn sink_checkpoint(cursor: &str) -> Result<()> {
    Ok(wit::sink::checkpoint(cursor)?)
}

pub(crate) fn sink_known_items() -> Result<Vec<(String, Option<String>)>> {
    Ok(wit::sink::known_items()?
        .into_iter()
        .map(|k| (k.key, k.version))
        .collect())
}

pub(crate) fn sink_cancelled() -> bool {
    wit::sink::cancelled()
}
